-- Bancada descartável. Nenhuma mensagem, nenhuma chamada de rede; rollback integral.
begin;
create temporary table d4 as select gen_random_uuid() shop,gen_random_uuid() person,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() plan,gen_random_uuid() grp,gen_random_uuid() cycle,null::jsonb job,null::jsonb body,null::jsonb step;
create function pg_temp.check_d4(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d4((select not enabled from public.whatsapp_care_cycle_policy),'Contrato novo não herda liberação do piloto anterior');
update public.whatsapp_send_controls set paused=false where scope='global';
update d4 set shop=(public.register_my_barbershop(gen_random_uuid(),'Ciclo Fictício','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select public.platform_create_whatsapp_channel(a,'Ciclo A') from d4;
select public.platform_create_whatsapp_channel(b,'Ciclo B') from d4;
update public.whatsapp_channels set display_phone=case id when (select a from d4) then '+5511800000111' else '+5511800000222' end,status='open' where id in(select a from d4 union all select b from d4);
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select a from d4 union all select b from d4);
select public.platform_plan_whatsapp_distribution(plan,array[shop],false) from d4;
select public.platform_apply_whatsapp_distribution(plan) from d4;
select pg_temp.check_d4((select jsonb_array_length(public.care_cycle_composition(shop))=2 from d4),'Composição da loja usa dois telefones físicos com controle confirmado');
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d4;
insert into public.memberships(user_id,barbershop_id,role) select person,shop,'customer' from d4;
insert into public.whatsapp_care_groups(id,barbershop_id,customer_id,customer_phone) select grp,shop,person,'+5511999999999' from d4;
insert into public.whatsapp_group_enrollments(group_id,profile_phone,profile_verified_at) select grp,null,null from d4;
insert into public.whatsapp_care_cycles(id,group_id,customer_phone,consented_numbers,creator_channel_id,creator_instance)
 select cycle,grp,'+5511999999999',public.care_cycle_composition(shop),(public.care_cycle_composition(shop)->0->>'id')::uuid,public.care_cycle_composition(shop)->0->>'instance' from d4;
update public.whatsapp_care_groups set current_cycle_id=(select cycle from d4) where id=(select grp from d4);
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Ter números e consentimento não ignora política desligada');
update public.whatsapp_care_cycle_policy set enabled=true;
select pg_temp.check_d4((select public.care_cycle_available(cycle) from d4),'Composição e adesão autenticada elegíveis para preparar, sem confirmar telefone');
update d4 set job=public.claim_care_cycle(cycle);
select pg_temp.check_d4((select job->>'token' is not null from d4),'Operador recebe posse com revisão fixada');
select pg_temp.check_d4((select public.claim_care_cycle(cycle) is null from d4),'Outra execução não toma lease em andamento');
update d4 set body=jsonb_build_object('operationId',job->>'creation_operation','cycleId',cycle,'subject','Notificações Ciclo Fictício • Cliente','customerJid','5511999999999@s.whatsapp.net','participants',jsonb_build_array(substring(job->'numbers'->1->>'phone' from 2)||'@s.whatsapp.net'),'brand',jsonb_build_object('shop_name','Ciclo Fictício','customer_name','Cliente','slug','ciclo-ficticio','timezone','America/Sao_Paulo'));
select public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body,repeat('a',64)) from d4;
select public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body,repeat('a',64)) from d4;
do $$begin begin perform public.seal_care_cycle_creation(cycle,(job->>'token')::uuid,'evo-ficticia',body||'{"subject":"Alterado"}',repeat('a',64)) from d4;raise exception 'FAIL: payload alterado aceito';exception when others then if sqlerrm like 'FAIL:%' then raise;end if;raise notice 'PASS: payload de criação não muda após ser lacrado';end;end $$;
update d4 set step=public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','initial',job->>'creator_instance',repeat('a',64));
select pg_temp.check_d4((select (step->>'execute')::boolean from d4),'Primeira execução recebe licença durável');
select pg_temp.check_d4((select (public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','initial',job->>'creator_instance',repeat('a',64))->>'execute')::boolean=false from d4),'Reentrega consulta a mesma licença e não inicia outra criação');
select public.finish_care_cycle_step(cycle,(job->>'token')::uuid,(step->>'id')::uuid,false) from d4;
select pg_temp.check_d4((select state='unknown' from public.whatsapp_care_cycle_steps,d4 where id=(step->>'id')::uuid),'Incerteza permanece durável');
do $$begin begin perform public.start_care_cycle_step(cycle,(job->>'token')::uuid,'create','outra',job->>'creator_instance',repeat('a',64)) from d4;raise exception 'FAIL: outra criação concedida';exception when others then if sqlerrm like 'FAIL:%' then raise;end if;raise notice 'PASS: revisão nova não concede segunda criação no mesmo ciclo';end;end $$;
select public.record_care_cycle_creation(cycle,(job->>'token')::uuid,'99887766-5555@g.us',date_trunc('second',clock_timestamp()),(date_trunc('second',clock_timestamp()) at time zone 'UTC'+interval '1 year') at time zone 'UTC') from d4;
select pg_temp.check_d4((select created_at is not null and expires_at=((created_at at time zone 'UTC')+interval '1 year') at time zone 'UTC' from public.whatsapp_care_cycles,d4 where id=cycle),'Validade de um ano deriva da criação comprovada');
select pg_temp.check_d4((select not controls_verified and state='creating' from public.whatsapp_care_groups,d4 where id=grp),'Criar não libera código nem presume cliente presente');
update public.whatsapp_care_cycles set state='customer_left' where id=(select cycle from d4);
select pg_temp.check_d4((select created_at is not null and expires_at=((created_at at time zone 'UTC')+interval '1 year') at time zone 'UTC' from public.whatsapp_care_cycles,d4 where id=cycle),'Saída do cliente não reinicia o ano');
update public.whatsapp_channels set platform_control_identity=null where id=(select b from d4);
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Retirar prova de isolamento interrompe autorização');
update public.whatsapp_channels set platform_control_identity=jsonb_build_object('phone',regexp_replace(display_phone,'[^0-9]','','g'),'instance',instance_name) where id=(select b from d4);
update public.whatsapp_care_cycles set expires_at=now()-interval '1 second',created_at=now()-interval '1 year'-interval '1 second',lease_until=null where id=(select cycle from d4);
select pg_temp.check_d4((select not public.care_cycle_available(cycle) from d4),'Vencimento bloqueia sem depender de cron');
update d4 set job=public.claim_care_cycle(cycle);
select pg_temp.check_d4((select job->>'state'='closing' from d4),'Ciclo vencido só recebe tarefa de encerramento');
delete from public.whatsapp_care_groups where id=(select grp from d4);
select pg_temp.check_d4((select group_id is null and state='closing' and creation_body is null and group_jid='99887766-5555@g.us' from public.whatsapp_care_cycles,d4 where id=cycle),'Exclusão de cadastro conserva fechamento mínimo sem nome/e-mail');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.claim_care_cycle(uuid)','execute'),'Cliente não obtém jobs internos');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.start_care_cycle_step(uuid,uuid,text,text,text,text)','execute'),'Navegador não cria licenças de provedor');
select pg_temp.check_d4(not has_table_privilege('service_role','public.whatsapp_care_cycles','select'),'Serviço opera somente via contratos definidos');
rollback;
